	@Test
	void loadDoesNotConnectToLoopbackHttp() throws Exception {
		byte[] turtle = "<urn:secret> <urn:predicate> <urn:value> .\n".getBytes(StandardCharsets.UTF_8);
		AtomicInteger requests = new AtomicInteger();
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/private.ttl", exchange -> {
			requests.incrementAndGet();
			exchange.getResponseHeaders().add("Content-Type", "text/turtle");
			exchange.sendResponseHeaders(200, turtle.length);
			try (var output = exchange.getResponseBody()) {
				output.write(turtle);
			}
		});
		server.start();
		try {
			assertServerLoadDenied("http://127.0.0.1:" + server.getAddress().getPort() + "/private.ttl");
			assertServerLoadDenied("http://localhost:" + server.getAddress().getPort() + "/private.ttl");
			assertThat(requests).hasValue(0);
		} finally {
			server.stop(0);
		}
	}

	@Test
	void trustedDatasetUsesMimeTypeAndConditionalLastModified() throws Exception {
		AtomicInteger requests = new AtomicInteger();
		AtomicReference<String> conditionalHeader = new AtomicReference<>();
		byte[] turtle = "<urn:secret> <urn:predicate> <urn:value> .\n".getBytes(StandardCharsets.UTF_8);
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/source", exchange -> {
			requests.incrementAndGet();
			conditionalHeader.set(exchange.getRequestHeaders().getFirst("If-Modified-Since"));
			if (conditionalHeader.get() != null) {
				exchange.sendResponseHeaders(304, -1);
				exchange.close();
				return;
			}
			exchange.getResponseHeaders().add("Content-Type", "text/turtle");
			exchange.getResponseHeaders().add("Last-Modified", "Wed, 21 Oct 2015 07:28:00 GMT");
			exchange.sendResponseHeaders(200, turtle.length);
			try (var output = exchange.getResponseBody()) {
				output.write(turtle);
			}
		});
		server.start();
		Repository repository = new DatasetRepository(new SailRepository(new MemoryStore()));
		repository.init();
		try {
			MockHttpServletRequest request = new MockHttpServletRequest();
			request.setAttribute("repository", repository);
			String origin = "http://127.0.0.1:" + server.getAddress().getPort();
			String query = "SELECT * FROM <" + origin + "/source> WHERE { ?s ?p ?o }";
			try (RepositoryConnection connection = RepositoryInterceptor.getRepositoryConnection(request)) {
				connection.getParserConfig()
						.set(RDFLoaderSettings.REMOTE_RESOURCE_OPENER,
								new ServerRemoteResourceOpener(origin));
				for (int i = 0; i < 2; i++) {
					try (var result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
						assertThat(result.hasNext()).isTrue();
					}
				}
			}
			assertThat(requests).hasValue(2);
			assertThat(conditionalHeader.get()).isEqualTo("Wed, 21 Oct 2015 07:28:00 GMT");
		} finally {
			repository.shutDown();
			server.stop(0);
		}
	}

